import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, SRGBColorSpace } = ctx.THREE;

  const group = new Group();
  group.name = config.id || 'hub-pricing-card-2-label';

  // ---- Atlas region (0,0,512,320) ----
  const rw = 512, rh = 320;
  const aspect = rw / rh;
  const planeW = 1.7;
  const planeH = planeW / aspect;

  // Base textured plane (ceramic grain)
  const geo = new PlaneGeometry(planeW, planeH, 1, 1);
  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    toneMapped: false,
  });

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    const img = tex.image;
    const tw = (img && (img.width || img.naturalWidth)) || rw;
    const th = (img && (img.height || img.naturalHeight)) || rh;
    // Atlas region anchored top-left. Three texture origin is bottom-left.
    tex.offset.set(0, (th - rh) / th);
    tex.repeat.set(rw / tw, rh / th);
    tex.needsUpdate = true;
    mat.map = tex;
    mat.needsUpdate = true;
  });

  const plane = new Mesh(geo, mat);
  group.add(plane);

  // ---- Engineered gradient veil (surface -> ink) ----
  const cBottom = new Color('#0b0b10');
  const cTop = new Color('#16161d');
  const gradGeo = new PlaneGeometry(planeW, planeH, 1, 1);
  const gradMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.6,
    side: DoubleSide,
    toneMapped: false,
  });
  gradMat.colorNode = mix(
    vec3(cBottom.r, cBottom.g, cBottom.b),
    vec3(cTop.r, cTop.g, cTop.b),
    uv().y
  );
  const gradPlane = new Mesh(gradGeo, gradMat);
  gradPlane.position.z = 0.005;
  group.add(gradPlane);

  // ---- Accent tick (signal red, small footprint) ----
  const accent = new Color('#ff2a38');
  const accentGeo = new PlaneGeometry(planeW * 0.14, 0.018, 1, 1);
  const accentMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    toneMapped: false,
  });
  accentMat.colorNode = vec3(accent.r, accent.g, accent.b);
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-planeW / 2 + planeW * 0.085, planeH / 2 - 0.12, 0.012);
  group.add(accentMesh);

  // ---- Text overlay ("Pricing 2") ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') || items[0];
  let textObj = null;
  if (headlineItem && ctx.fontAtlas) {
    textObj = ctx.fontAtlas.createText(String(headlineItem.text), {
      fontSize: 39,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 540,
      letterSpacingPx: 1.5,
    });
    textObj.position.set(-planeW / 2 + 0.18, -0.06, 0.025);
    group.add(textObj);
  }

  // ---- Entrance: weighted-settle ----
  const baseY = config.scenePosition ? config.scenePosition[1] : 1;
  const tl = gsap.timeline();
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition[0],
      baseY + 0.18,
      config.scenePosition[2]
    );
  } else {
    group.position.y = baseY + 0.18;
  }
  tl.to(group.position, { y: baseY, duration: 0.7, ease: 'power3.out' });
  tl.to(group.position, {
    y: baseY - 0.012,
    duration: 0.5,
    ease: 'power2.inOut',
    yoyo: true,
    repeat: 1,
  }, '>');

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    gradGeo.dispose();
    accentGeo.dispose();
    mat.dispose();
    gradMat.dispose();
    accentMat.dispose();
    if (textObj) {
      group.remove(textObj);
      textObj.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
          else o.material.dispose();
        }
      });
    }
  };

  return group;
}
